class Solution:
    def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head: return head
        o, e = head, head.next; eh = e
        while e and e.next:
            o.next = e.next; o = o.next
            e.next = o.next; e = e.next
        o.next = eh
        return head
